beforeExample:
class MyClass {
    void check(String newCharset) {
        if (newCharset == null || newCharset.trim().length() == 0) {
            System.out.println("Empty or blank");
        }
    }
}

afterExample:
class MyClass {
    void check(String newCharset) {
        if (newCharset == null || newCharset.isBlank()) {
            System.out.println("Empty or blank");
        }
    }
}

negativeExample:
class MyClass {
    void check(String newCharset) {
        // Does not match: uses isEmpty() instead of trim().length() == 0
        if (newCharset == null || newCharset.isEmpty()) {
            System.out.println("Empty or null");
        }
        // Does not match: compares to 1, not 0
        if (newCharset != null && newCharset.trim().length() == 1) {
            System.out.println("Single char after trim");
        }
        // Would not match if compiled with Java 10 or earlier due to sourceVersionGE(11) guard
    }
}
